[120] = { en = "Messenger to Stormwind", tier = 1,
  t = "Boodschapper naar Stormwind",
  d = "Dit zijn zware tijden, $c. Het dorp wordt steeds aangevallen. Zonder versterking verliezen we zeker. Ik geef je nu een bericht, en het is heel belangrijk. Breng dit rapport meteen naar General Marcus Jonathan in Stormwind. Kom daarna direct terug naar mij. Vertel me dan het nieuws, goed of slecht. $b$bSchiet nu op!",
  o = "Magistrate Solomon heeft je een rapport gegeven. Je moet het naar General Marcus Jonathan in Stormwind brengen. De rechter wil dat je terugkomt zodra je het hebt afgeleverd.",
  p = "Wat heb je daar?",
  c = "Op de plaats rust, $C.$b$bMagistrate Solomon is een edele leider. Zijn woorden zijn heel belangrijk voor mij. Ik ga de koning om raad vragen. Ik leg hem de situatie duidelijk uit. Zeg tegen de goede rechter dat het leger van Stormwind hem steunt. We sturen versterking zodra Zijne Majesteit het bevel geeft.",
  g = { {"zware tijden", "hard times, trying times"}, {"aangevallen", "attacked (aanvallen)"}, {"versterking", "reinforcements"}, {"rapport", "report"}, {"afgeleverd", "delivered (afleveren)"}, {"rechter", "judge"}, {"Op de plaats rust", "At ease (military command)"}, {"edele", "noble (edel)"}, {"om raad vragen", "to ask for advice, to seek counsel"}, {"steunt", "supports (steunen)"}, {"Zijne Majesteit", "His Majesty"}, {"bevel", "order, command"} },
},

[121] = { en = "Messenger to Stormwind", tier = 1,
  t = "Boodschapper naar Stormwind",
  d = "Ik wacht op een antwoord van de koning. Breng intussen deze brief naar Magistrate Solomon. $b$bJe mag gaan, $c!",
